2. **解析元数据**
```javascript
const metaRegex = /^- (.+?): (.+)$/gm;
const metadata = {};
for (const match of section.matchAll(metaRegex)) {
  const key = match[1].trim();
  const value = match[2].trim();

  if (key === '创建时间' || key === '最后修改') {
    metadata[key] = new Date(value).getTime();
  } else if (key === '访问次数') {
    metadata[key] = parseInt(value) || 0;
  } else {
    metadata[key] = value;
  }
}
```

